"""Additional reference entries reviewed against product documentation and guide scope."""
EXTRA={
'fortigate-cli-essentials':('get system ha status','Inspect high availability state','Check whether the appliance is standalone or part of an HA cluster. Compare member roles and synchronization status with the intended design.'),
'cisco-ios-essentials':('show logging','Review buffered system events','Compare interface or routing messages with the incident time. Logging configuration and buffer retention determine which events are available.'),
'fortigate-routing-arp':('get router info routing-table details <destination-ip>','Inspect the route selected for one destination','Replace the placeholder with the destination address. Compare the selected route, outgoing interface and gateway with the expected forward path.'),
'cisco-interface-diagnostics':('show interfaces','Inspect detailed interface state','Read input errors, output errors, drops and link transitions for the affected port. Compare two samples because counters may include old events.'),
'fortigate-vpn-health':('get router info routing-table all','Verify routes toward the remote network','A live tunnel needs a route and matching policy as well as an active security association. Compare the selected egress interface with the expected VPN path.'),
'cisco-vlans-trunks':('show mac address-table','Inspect learned MAC addresses','Compare the learned VLAN and port against the endpoint location. An inactive endpoint may age out, so an absent entry is not conclusive by itself.'),
'fortigate-ha-system-health':('diagnose system ha status','Inspect HA diagnostic status','Compare cluster state and member details with the expected primary and secondary roles. Check both units before drawing conclusions about synchronization.'),
'cisco-routing-basics':('show ip route <destination-ip>','Inspect the route to a destination','Replace the placeholder with an IPv4 destination. Review the selected prefix, next hop and interface, then check the return route independently.'),
'fortigate-session-inspection':('get router info routing-table all','Check the route alongside session information','Use the active route table to establish the expected egress path. Existing sessions can persist across changes, so record timing before comparing observations.'),
'cisco-neighbor-discovery':('show interfaces description','Map port descriptions to the topology','Compare interface descriptions with discovered neighbors and the physical cabling plan. Descriptions are manually maintained and can be stale.'),
'linux-network-essentials':('ip -s link show','Inspect interface counters','Compare errors and drops on the affected link over time. The counters describe interface activity and do not independently identify an application fault.'),
'cloud-network-fundamentals':('Network ACL','A subnet-level traffic control in some cloud platforms','Check the platform’s direction, rule ordering and stateful or stateless behavior. Security group and network ACL semantics are provider-specific.'),
'windows-network-troubleshooting':('Get-DnsClientServerAddress','List configured DNS servers by interface','Match the server addresses to the adapter used by the affected connection. A configured server can still be unreachable or return an unexpected answer.'),
'windows-services-and-event-logs':('Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,LastBootUpTime','Inspect operating-system version and boot time','Compare the last boot time with the incident timeline. A restart can explain a brief interruption but does not by itself identify the trigger.'),
'active-directory-users-and-groups':("Get-ADUser -Identity 'jdoe' -Properties MemberOf",'Inspect direct group references on an account','Replace jdoe with the account. MemberOf describes direct membership references; evaluate nested groups and resource permissions separately.'),
'active-directory-replication-health':("Get-ADReplicationPartnerMetadata -Target 'corp-DC01'",'Inspect replication partner metadata','Replace corp-DC01 with the affected domain controller. Compare last attempt and last success for each inbound partner and naming context.'),
'microsoft-graph-connection-and-user-lookup':('Get-MgUser -Top 10','Inspect a small user sample','This returns a bounded sample with default properties. It is useful for verifying read access, but it is not a complete inventory or tenant count.'),
'microsoft-graph-query-and-paging-basics':('Get-MgUser -Top 10','Inspect a small first page','Use a small sample to confirm connectivity and access before a tenant-wide query. Do not treat a limited result as a complete count.'),
'entra-id-sign-in-investigation':('Sign-in event → Troubleshooting + support','Review the event’s diagnostic context','Compare the presented error and correlation ID with the authentication steps and applied policies. Escalate with the timestamp and tenant context.'),
'entra-id-devices-and-tenant-overview':('dsregcmd /status → Diagnostic Data','Review registration diagnostics on the device','Record the diagnostic output in the relevant user context and compare the tenant and device identity with the portal record. Redact sensitive identifiers before sharing.'),
'exchange-online-mailbox-inspection':("Get-EXOMailboxStatistics -Identity 'user@example.com'",'Inspect mailbox size and item count','Replace the example address with the intended mailbox. Compare the returned size with the configured warning and send quotas; permissions and property availability vary.'),
'exchange-online-message-tracing':("Get-MessageTraceV2 -RecipientAddress 'recipient@example.com' -StartDate $start -EndDate $end",'Trace a recent recipient','Replace the address and use the bounded time window from the walkthrough. Compare MessageTraceId and timestamps with the reported message.'),
'azure-subscription-and-resource-inventory':('az group list --output table','List resource groups in the active subscription','Confirm the active subscription first, then compare resource-group names and locations with the deployment inventory. RBAC limits what is visible.'),
'azure-virtual-network-inspection':('az network vnet show --resource-group rg-example --name vnet-example --output json','Inspect one virtual network','Replace the resource group and VNet name. Review address space and subnet references, then compare the output with the intended environment.'),
'sophos-firewall-cli-health-checks':('system diagnostics show cpu','Inspect CPU diagnostics','Compare the current reading with the same appliance’s baseline and time of the reported issue. A single sample does not establish sustained load.'),
'sophos-firewall-traffic-investigation':('Log viewer → filter by rule ID','Review events for the matching firewall rule','After identifying the rule from a traffic event, narrow the time window and compare source, destination and actions. Missing records can reflect logging settings.'),
'juniper-junos-cli-essentials':('show system uptime','Inspect boot and system timing','Compare boot time and current system time with the incident. On supported Junos platforms this also provides useful timing context for recent configuration activity.'),
'juniper-routes-and-neighbor-checks':('show route summary','Summarize route-table state','Review table and protocol counts as a baseline. A summary cannot replace checking the exact prefix and selected next hop in the relevant routing instance.'),
'ubiquiti-unifi-device-connectivity':('UniFi Network → Settings → Networks','Review the management network','Compare the management network and VLAN with the upstream switch-port settings. Menu names can vary by Network version; inspect before making changes.'),
'ubiquiti-unifi-switch-port-checks':('Devices → Switch → Overview','Review switch health and uplink','Compare the uplink, device status and recent health indicators with the affected port. A healthy switch overview does not rule out a single-port or endpoint issue.'),
'hpe-proliant-ilo-health-overview':('Information → iLO Event Log','Review management-controller events','Compare iLO events with the Integrated Management Log and the incident time. Preserve logs before replacing components or clearing entries.'),
'hpe-aruba-cx-switching-essentials':('show system','Inspect switch system information','Record the system identity and compare the hardware and software context with the intended switch. Command output varies with AOS-CX platform and release.'),
'dell-poweredge-idrac-health-checks':('racadm getversion','Read controller firmware version','Compare the controller firmware with the approved server baseline and support information. Version inspection does not apply an update.'),
'dell-poweredge-hardware-inventory':('racadm getsel','Inspect hardware event records','Compare component inventory with recent hardware events and the maintenance timeline. Preserve event records for troubleshooting before clearing logs.'),
'dell-data-domain-capacity-and-health':('replication status','Inspect replication context state','Compare the enabled state and last synchronization for the expected destination. An idle connection may be normal when there is no new data to replicate.'),
'dell-data-domain-replication-checks':('filesys status','Check the filesystem during replication diagnosis','A replication issue can accompany a filesystem or capacity problem. Inspect both systems and correlate their state with active alerts.'),
'kali-nmap-discovery-essentials':('nmap -sT -p 443 --reason <lab-ip>','Show the reason for the reported port state','Replace the placeholder with a single authorized host. Compare the reason and timing with firewall logs; a filtered state is not proof of a specific filtering device.'),
'kali-wireshark-packet-analysis':('tcp.analysis.retransmission','Display TCP retransmission indications','Investigate the affected stream and timing, then compare with capture location and packet loss. Capture loss or asymmetric visibility can affect analysis.'),
'kali-burp-suite-proxy-basics':('Target → Site map','Review discovered lab requests','Use the site map to review hosts and paths observed during the authorized session. Confirm that the host is in scope before continuing any testing.')}
